674	\begin{lemma}[Fourier expansion of Pauli observables]\label{lem:pauli-observable-expansion}
675		\uses{def:generalized-pauli, def:subfield-trace}
676		For every integer $n \ge 1$, all $W \in \{X, Z\}$, and all $a \in \F_q^n$,
677		% Paper equation label kept on the display it names.
678		\begin{equation}\label{eq:pauli-obs-proj}
679			\tau^W(a) = \sum_{b \in \F_q^n} \omega^{\tr(a \cdot b)}\, \tau^W_b\;,
680		\end{equation}
681		and conversely
682		\begin{equation}\label{eq:pauli-inversion-0}
683			\E_{\ba \sim \F_q^n}\, \omega^{-\tr(\ba \cdot b)}\, \tau^W(\ba)
684			= \sum_{b' \in \F_q^n} \E_{\ba \sim \F_q^n}\,
685			\omega^{\tr(\ba \cdot (b' - b))}\, \tau^W_{b'}
686			= \tau^W_b\;.
687		\end{equation}
688	\end{lemma}
689	\begin{proof}
690		\uses{def:generalized-pauli, lem:cancellation}
691		Each $\ket{b_W}$ is an eigenvector of $\tau^W(a)$ with eigenvalue
692		$\omega^{\tr(a \cdot b)}$: for $W = Z$ this is immediate from the
693		definition, and for $W = X$ it follows from the single-qudit computation
694		$\tau^X(a)\ket{e_X} = \omega^{\tr(ae)}\ket{e_X}$, applied factor by factor.
695		Expanding $\tau^W(a)$ in the orthonormal eigenbasis
696		$\{\ket{b_W}\}_{b \in \F_q^n}$ gives the first display. For the inversion,
697		substitute the first display and exchange the order of summation; by
698		Lemma~\ref{lem:cancellation} applied with $V = \F_q^n$ (so that
699		$V^\perp = \{0\}$), the inner expectation vanishes unless $b' = b$, where
700		it equals $1$.
701	\end{proof}
