 550	\section{Generalized Pauli observables}
 551	% Paper label sec:generalized-pauli kept for cross-reference fidelity.
 552	\label{sec:generalized-pauli}
 553	
 554	\begin{definition}[Generalized Pauli observables]\label{def:generalized-pauli}
 555		\lean{MIPStarRE.QPBT.primeTauShift, MIPStarRE.QPBT.primeTauPhase}
 556		\lean{MIPStarRE.QPBT.primeTauObservable}
 557		\uses{def:subfield-trace, def:lin-reg}
 558		Let $p$ be a prime and $\omega = e^{2\pi i/p}$. The \emph{generalized Pauli
 559		observables over $\F_p$} are the unitaries on $\C^{\F_p}$ given by
 560		\begin{equation}\label{eq:pauli-fp}
 561			\sigma^X(a) = \sum_{j \in \F_p} \ket{j + a}\bra{j}
 562			\qquad \text{and} \qquad
 563			\sigma^Z(b) = \sum_{j \in \F_p} \omega^{bj} \ket{j}\bra{j}
 564		\end{equation}
 565		for $a, b \in \F_p$, with arithmetic over $\F_p$. For $q = p^k$, the
 566		\emph{generalized Pauli observables over $\F_q$} are the unitaries on
 567		$\C^{\F_q}$
 568		\[
 569			\tau^X(a) = \sum_{j \in \F_q} \ket{j + a}\bra{j}
 570			\qquad \text{and} \qquad
 571			\tau^Z(b) = \sum_{j \in \F_q} \omega^{\tr(bj)} \ket{j}\bra{j}
 572		\]
 573		for $a, b \in \F_q$, where $\tr$ here denotes $\tr_{q \to p}$
 574		(Definition~\ref{def:subfield-trace}); for admissible $q$ this agrees with
 575		the standing shorthand, $p = 2$, and $\omega = -1$, so that all phases are
 576		signs. All the $\tau^X$ operators commute with one another, as do all the
 577		$\tau^Z$ operators. Their common eigenbases consist of the vectors
 578		$\ket{e_W}$, labeled by $e \in \F_q$ and $W \in \{X, Z\}$, given by
 579		\[
 580			\ket{e_X} = \frac{1}{\sqrt{q}} \sum_{j \in \F_q}
 581			\omega^{-\tr(ej)} \ket{j}\;, \qquad
 582			\ket{e_Z} = \ket{e}\;;
 583		\]
 584		the Fourier transform
 585		\begin{equation}\label{eq:fourier-f}
 586			F = \frac{1}{\sqrt{q}} \sum_{a, b \in \F_q}
 587			\omega^{-\tr(ab)} \ket{a}\bra{b}
 588		\end{equation}
 589		maps the computational ($Z$) eigenbasis to the $X$ eigenbasis. We write
 590		$\{\tau^W_e\}_{e \in \F_q}$ for the projective measurement whose elements
 591		are the rank-one projectors onto the vectors of the $W$ eigenbasis. For
 592		systems of $n$ qudits, we write, for $W \in \{X,Z\}$ and $a \in \F_q^n$,
 593		\[
 594			\tau^W(a) = \tau^W(a_1) \ot \dots \ot \tau^W(a_n)\;, \qquad
 595			\ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}
 596		\]
 597		for $e \in \F_q^n$, with associated rank-one projectors $\tau^W_e$.
 598	\end{definition}
 599	
 600	\begin{lemma}[Product and twisted commutation relations]\label{lem:twisted-commutation}
 601		\lean{MIPStarRE.QPBT.primeTauObservable_mul}
 602		\lean{MIPStarRE.QPBT.primeTauObservable_pow}
 603		\lean{MIPStarRE.QPBT.primeTauObservable_pow_char}
 604		\lean{MIPStarRE.QPBT.primeTauObservable_isUnitary}
 605		\lean{MIPStarRE.QPBT.primeTauObservable_eigenvalue_pow_char}
 606		\lean{MIPStarRE.QPBT.primeTauObservable_X_mul_Z}
 607		\leanok
 608		\uses{def:generalized-pauli, def:subfield-trace, def:dot-product-orthogonal}
 609		Let $q = p^k$, let $n \ge 1$ be an integer, and let $W \in \{X, Z\}$.
 610		\begin{enumerate}
 611			\item For all $a, a' \in \F_q$ and $b \in \F_p$,
 612			      \begin{equation}\label{eq:pauli-product-power}
 613				      \tau^W(a)\, \tau^W(a') = \tau^W(a + a')
 614				      \qquad \text{and} \qquad
 615				      \bigl(\tau^W(a)\bigr)^b = \tau^W(ab)\;;
 616			      \end{equation}
 617			      in particular $\bigl(\tau^W(a)\bigr)^p = \Id$. By the explicit
 618			      definitions each $\tau^W(a)$ is unitary, and its eigenvalues are
 619			      $p$-th roots of unity.
 620			\item For all $a, b \in \F_q^n$,
 621			      % Paper equation label kept on the display it names.
 622			      \begin{equation}\label{eq:twisted-fq}
 623				      \tau^X(a)\, \tau^Z(b)
 624				      = \omega^{-\tr(a \cdot b)}\, \tau^Z(b)\, \tau^X(a)\;,
 625			      \end{equation}
 626			      where $a \cdot b = \sum_{i=1}^n a_i b_i \in \F_q$. The case
 627			      $q = p$, $n = 1$ reads
 628			      \begin{equation}\label{eq:twisted-fp}
 629				      \sigma^X(a)\, \sigma^Z(b)
 630				      = \omega^{-ab}\, \sigma^Z(b)\, \sigma^X(a)
 631				      \qquad \text{for all } a, b \in \F_p\;.
 632			      \end{equation}
 633		\end{enumerate}
 634	\end{lemma}
 635	\begin{proof}
 636		\uses{def:generalized-pauli, def:subfield-trace}
 637		All identities are verified on computational basis states. For the product
 638		relations with $W = X$, shifting twice by $a'$ and $a$ equals shifting by
 639		$a + a'$; with $W = Z$, the phases $\omega^{\tr(aj)}\omega^{\tr(a'j)}$
 640		combine by $\F_q$-linearity of the trace, and the power relation follows by
 641		iterating. For the scalar twisted commutation,
 642		$\tau^X(a)\tau^Z(b)\ket{j} = \omega^{\tr(bj)}\ket{j + a}$, while
 643		$\tau^Z(b)\tau^X(a)\ket{j} = \omega^{\tr(b(j+a))}\ket{j + a} =
 644		\omega^{\tr(ab)}\,\omega^{\tr(bj)}\ket{j + a}$. The multi-qudit relation
 645		follows by applying the scalar relation factor by factor and summing the
 646		exponents, using $\tr(a \cdot b) = \sum_i \tr(a_i b_i)$. For $q = p$ the
 647		trace is the identity map, which gives \eqref{eq:twisted-fp}.
 648	\end{proof}
 649	
 650	\begin{lemma}[Fourier cancellation over a subspace]\label{lem:cancellation}
 651		\lean{MIPStarRE.QPBT.ffChar_dotProduct_submodule_expect_eq_zero}
 652		\leanok
 653		\uses{def:dot-product-orthogonal, def:subfield-trace}
 654		Let $V$ be a subspace of $\F_q^k$ and let $\omega = e^{2\pi i/p}$, where
 655		$p$ is the characteristic of $\F_q$ and $\tr = \tr_{q \to p}$. For all
 656		$v \notin V^\perp$,
 657		\[
 658			\E_{\bu \sim V}\, \omega^{\tr(\bu \cdot v)} = 0\;,
 659		\]
 660		where the expectation is over a uniformly random vector $\bu$ in $V$.
 661	\end{lemma}
 662	\begin{proof}
 663		This is Fact 3.2 of \cite{Natarajan2018NEEXP}. Since $v \notin V^\perp$,
 664		the $\F_q$-linear functional $u \mapsto u \cdot v$ is not identically zero
 665		on $V$, hence surjective onto $\F_q$; composing with the nonzero map $\tr$
 666		shows that there is $u_0 \in V$ with $\tr(u_0 \cdot v) \neq 0$. Writing $C$
 667		for the expectation, translation invariance of the uniform distribution on
 668		$V$ gives
 669		$C = \E_{\bu \sim V}\, \omega^{\tr((\bu + u_0) \cdot v)}
 670		= \omega^{\tr(u_0 \cdot v)}\, C$, and $\omega^{\tr(u_0 \cdot v)} \neq 1$
 671		forces $C = 0$.
 672	\end{proof}
 673	
 674	\begin{lemma}[Fourier expansion of Pauli observables]\label{lem:pauli-observable-expansion}
 675		\uses{def:generalized-pauli, def:subfield-trace}
 676		For every integer $n \ge 1$, all $W \in \{X, Z\}$, and all $a \in \F_q^n$,
 677		% Paper equation label kept on the display it names.
 678		\begin{equation}\label{eq:pauli-obs-proj}
 679			\tau^W(a) = \sum_{b \in \F_q^n} \omega^{\tr(a \cdot b)}\, \tau^W_b\;,
 680		\end{equation}
 681		and conversely
 682		\begin{equation}\label{eq:pauli-inversion-0}
 683			\E_{\ba \sim \F_q^n}\, \omega^{-\tr(\ba \cdot b)}\, \tau^W(\ba)
 684			= \sum_{b' \in \F_q^n} \E_{\ba \sim \F_q^n}\,
 685			\omega^{\tr(\ba \cdot (b' - b))}\, \tau^W_{b'}
 686			= \tau^W_b\;.
 687		\end{equation}
 688	\end{lemma}
 689	\begin{proof}
 690		\uses{def:generalized-pauli, lem:cancellation}
 691		Each $\ket{b_W}$ is an eigenvector of $\tau^W(a)$ with eigenvalue
 692		$\omega^{\tr(a \cdot b)}$: for $W = Z$ this is immediate from the
 693		definition, and for $W = X$ it follows from the single-qudit computation
 694		$\tau^X(a)\ket{e_X} = \omega^{\tr(ae)}\ket{e_X}$, applied factor by factor.
 695		Expanding $\tau^W(a)$ in the orthonormal eigenbasis
 696		$\{\ket{b_W}\}_{b \in \F_q^n}$ gives the first display. For the inversion,
 697		substitute the first display and exchange the order of summation; by
 698		Lemma~\ref{lem:cancellation} applied with $V = \F_q^n$ (so that
 699		$V^\perp = \{0\}$), the inner expectation vanishes unless $b' = b$, where
 700		it equals $1$.
 701	\end{proof}
 702	
 703	Since only admissible field sizes $q = 2^k$ arise in the Pauli basis test, the
 704	maximally entangled state $\ket{\mathrm{EPR}_q}$ and the qudit Pauli
 705	projectors are isomorphic to tensor products of qubit EPR states
 706	$\ket{\mathrm{EPR}_2}$ and qubit Pauli projectors. This is the content of the
 707	next lemma, which is what allows the Pauli basis test to self-test Pauli
 708	observables and maximally entangled states over \emph{qubits}
 709	(Chapter~\ref{chap:qpbt-test}).
 710	
 711	\begin{lemma}[Qudit-to-qubit isomorphism]\label{lem:pauli-binary}
 712		\lean{MIPStarRE.QPBT.qubitPauliProj, MIPStarRE.QPBT.exists_qubitIsometry}
 713		\leanok
 714		\uses{def:admissible-size, def:subfields-kappa, def:binary-representation,
 715			def:generalized-pauli, def:EPR}
 716		For all admissible field sizes $q = 2^k$ and integers $L \ge 0$, there
 717		exists an isomorphism $\phi : (\C^q)^{\ot L} \to (\C^2)^{\ot Lk}$ such that
 718		\begin{equation}\label{eq:epr-q-to-epr-2}
 719			\phi \ot \phi\, \ket{\mathrm{EPR}_q}^{\ot L}
 720			= \ket{\mathrm{EPR}_2}^{\ot Lk}
 721		\end{equation}
 722		(applying the natural identifications between
 723		$(\C^q)^{\ot L} \ot (\C^q)^{\ot L}$ and $(\C^q \ot \C^q)^{\ot L}$, and
 724		between $(\C^2)^{\ot Lk} \ot (\C^2)^{\ot Lk}$ and
 725		$(\C^2 \ot \C^2)^{\ot Lk}$). Moreover, for all $W \in \{X, Z\}$ and all
 726		$u \in \F_q^L$,
 727		\begin{equation}\label{eq:pauli-q-to-pauli-2}
 728			\tau^W_u = \phi^\dagger\,
 729			\Bigl(\bigotimes_{i=1}^L \bigotimes_{j=1}^k
 730			\sigma^W_{u_{ij}}\Bigr)\, \phi\;.
 731		\end{equation}
 732		Here $(u_{ij})_{i,j}$ is the array of $\F_2$ values with
 733		$u_i = \sum_j u_{ij} e_j$ for all $i \in \{1, \dots, L\}$, where
 734		$\{e_1, \dots, e_k\}$ is the fixed self-dual normal basis of $\F_q$ over
 735		$\F_2$ of Definition~\ref{def:binary-representation}; and for
 736		$i \in \{1, \dots, L\}$ and $j \in \{1, \dots, k\}$ the $(i,j)$-th factor
 737		$\sigma^W_{u_{ij}}$ denotes the projector
 738		$\frac{1}{2}\bigl(\Id + (-1)^{u_{ij}} \sigma^W(1)\bigr)$ acting on the
 739		$s$-th qubit, where $s = (i-1)k + j$.
 740		We index the product coordinates from zero: values $(i-1,j-1)$ correspond to
 741		the paper's pair $(i,j)$.
 742	\end{lemma}
 743	\begin{proof}
 744		\uses{lem:pauli-observable-expansion, lem:downsize_field,
 745			lem:twisted-commutation}
 746		Define the isometry $\theta : \C^q \to (\C^2)^{\ot k}$ by
 747		$\theta\ket{a} = \ket{a_1} \ot \dots \ot \ket{a_k}$, where
 748		$\kappa(a) = (a_1, \dots, a_k)$ is the binary representation with respect
 749		to the fixed basis; since $\kappa$ is a bijection, $\theta$ is a unitary
 750		and $\theta \ot \theta\, \ket{\mathrm{EPR}_{2^k}} =
 751		\ket{\mathrm{EPR}_2}^{\ot k}$. For $a \in \F_q$ with
 752		$\kappa(a) = (a_1, \dots, a_k)$, the inversion formula of
 753		Lemma~\ref{lem:pauli-observable-expansion} gives
 754		$\tau^W_a = \E_{b \in \F_q} (-1)^{\tr(ab)}\, \tau^W(b)$; writing
 755		$b = \sum_j b_j e_j$, self-duality of the basis gives
 756		$b_j = \tr(b e_j)$ (item 1 of Lemma~\ref{lem:downsize_field}) and hence
 757		$\tr(ab) = \sum_j a_j b_j$. The product relation of
 758		Lemma~\ref{lem:twisted-commutation} factors
 759		$\tau^W(b) = \prod_j \tau^W(b_j e_j)$, so the expectation factors over
 760		independent $b_1, \dots, b_k \in \F_2$. A computation on basis states shows
 761		that for all $c \in \F_2$, $\tau^W(c e_j) = \theta^\dagger\,
 762		\sigma^{W,j}(c)\, \theta$, where $\sigma^{W,j}(c)$ is the identity for
 763		$c = 0$ and the Pauli $W$ observable acting on the $j$-th qubit of
 764		$(\C^2)^{\ot k}$ for $c = 1$. Averaging,
 765		$\E_{b_j \in \F_2} (-1)^{a_j b_j} \sigma^W(b_j) =
 766		\frac{1}{2}\bigl(\Id + (-1)^{a_j}\sigma^W(1)\bigr) = \sigma^W_{a_j}$,
 767		whence $\tau^W_a = \theta^\dagger \bigl(\bigotimes_j
 768		\sigma^W_{a_j}\bigr) \theta$. Taking $\phi = \theta^{\ot L}$ and tensoring
 769		the last identity over the $L$ qudits, using
 770		$\tau^W_u = \bigotimes_{i=1}^L \tau^W_{u_i}$, yields both displayed
 771		identities.
 772	\end{proof}
 773	
 774	\begin{remark}\label{rem:pauli-binary-source}
 775		In the source statement of Lemma~\ref{lem:pauli-binary} in
 776		\cite{Ji2020MIPStar}, the index range of the qubit factor is printed as
 777		$j \in \{1, \dots, q\}$; the intended range, used above, is
 778		$j \in \{1, \dots, k\}$, as the $i$-th qudit is mapped to $k$ qubits. The
 779		source also quantifies over arbitrary integers $L$; the statement above
 780		takes $L$ to be a natural number, including zero, and uses the usual
 781		empty-product convention for the tensor powers when $L=0$.
 782	\end{remark}

